    /** 8500-READTRNX-READ. */
    private int p19() {
        // IF WS-SAVE-CARD = TRNX-CARD-NUM
        if (Cobol.compare(f5_TRNX_CARD_NUM, f69_WS_SAVE_CARD, CS) == 0) {
            // ADD 1 TO TR-CNT
            BigDecimal t120 = D1;
            f61_TR_CNT = Cobol.binary(BigDecimal.valueOf(f61_TR_CNT).add(t120), 4, true, false, CS);
        } else {
            // MOVE TR-CNT TO WS-TRCT (CR-CNT)
            Cobol.move(BigDecimal.valueOf(f61_TR_CNT), f160_WS_TRCT.at(BigDecimal.valueOf(f60_CR_CNT).intValue(), 2), CS);
            // ADD 1 TO CR-CNT
            BigDecimal t122 = D1;
            f60_CR_CNT = Cobol.binary(BigDecimal.valueOf(f60_CR_CNT).add(t122), 4, true, false, CS);
            // MOVE 1 TO TR-CNT
            f61_TR_CNT = 1L;
        }
        // MOVE TRNX-CARD-NUM TO WS-CARD-NUM (CR-CNT)
        Cobol.move(f5_TRNX_CARD_NUM, f154_WS_CARD_NUM.at(BigDecimal.valueOf(f60_CR_CNT).intValue(), 3356), CS);
        // MOVE TRNX-ID TO WS-TRAN-NUM (CR-CNT, TR-CNT)
        Cobol.move(f6_TRNX_ID, f156_WS_TRAN_NUM.at(BigDecimal.valueOf(f60_CR_CNT).intValue(), 3356).at(BigDecimal.valueOf(f61_TR_CNT).intValue(), 334), CS);
        // MOVE TRNX-REST TO WS-TRAN-REST (CR-CNT, TR-CNT)
        Cobol.move(f7_TRNX_REST, f157_WS_TRAN_REST.at(BigDecimal.valueOf(f60_CR_CNT).intValue(), 3356).at(BigDecimal.valueOf(f61_TR_CNT).intValue(), 334), CS);
        // MOVE TRNX-CARD-NUM TO WS-SAVE-CARD
        f69_WS_SAVE_CARD = Cobol.moveText(f5_TRNX_CARD_NUM, 16, CS);
        // MOVE 'TRNXFILE' TO WS-M03B-DD
        Cobol.move("TRNXFILE", f72_WS_M03B_DD, CS);
        // SET M03B-READ TO TRUE
        Cobol.move("R", f73_WS_M03B_OPER, CS);
        // MOVE SPACES TO WS-M03B-FLDT
        Cobol.moveFigurative(Figurative.SPACES, f77_WS_M03B_FLDT, CS);
        // CALL 'CBSTM03B' USING WS-M03B-AREA
        Cbstm03bLkM03bArea arg124 = out_Cbstm03bLkM03bArea(f71_WS_M03B_AREA.storage(), f71_WS_M03B_AREA.offset());
        int rc125 = cbstm03bService.getObject().handleCall(arg124);
        in_Cbstm03bLkM03bArea(arg124, f71_WS_M03B_AREA.storage(), f71_WS_M03B_AREA.offset());
        Cobol.store(f183_GG_RETURN_CODE, BigDecimal.valueOf(rc125), false, CS);
        // EVALUATE WS-M03B-RC
        if ((Cobol.compare(f74_WS_M03B_RC, "00", CS) == 0)) {
            // MOVE WS-M03B-FLDT TO TRNX-RECORD
            Cobol.move(f77_WS_M03B_FLDT, f3_TRNX_RECORD, CS);
            // GO TO 8500-READTRNX-READ
            if (true) return GOTO | 19;
        } else if ((Cobol.compare(f74_WS_M03B_RC, "10", CS) == 0)) {
            // GO TO 8599-EXIT
            if (true) return GOTO | 20;
        } else if (true) {
            // DISPLAY 'ERROR READING TRNXFILE'
            Sysout.display("ERROR READING TRNXFILE");
            // DISPLAY 'RETURN CODE: ' WS-M03B-RC
            Sysout.display("RETURN CODE: ", Cobol.displayText(f74_WS_M03B_RC, CS));
            // PERFORM 9999-ABEND-PROGRAM
            perform(25, 25);
        }
        return 20;
    }

